/**
 * Opening one documented example in StackBlitz.
 *
 * The project is generated by `pnpm gen` from the example's own file — the
 * same file the Code tab shows and the Preview tab renders — and the registry
 * items it needs, which the browser reads from `/r/` exactly as `zoblocks add`
 * does. Nothing is cloned and nothing is rewritten on the way out; see
 * scripts/gen/emit/sandboxes.ts and src/lib/sandbox-project.ts.
 *
 * The button appears for every example in `SANDBOXES`, which the generator
 * derives and `pnpm sandboxes:check` proves compiles. An example that cannot
 * run says why in `NOT_RUNNABLE` rather than in a list kept here by hand.
 *
 * `openProject` posts a form to a new tab, and a browser lets that happen only
 * inside the click. So the project is fetched before the click — when the card
 * nears the viewport, or on hover or focus — and the click itself only opens.
 */

import sdk from "@stackblitz/sdk";
import { SANDBOXES } from "@/lib/generated/sandboxes";
import {
  assembleProject,
  registryUrl,
  sandboxUrl,
  type RegistryDocument,
  type SandboxManifest,
  type SandboxProject,
} from "@/lib/sandbox-project";

export function isRunnable(component: string, id: string): boolean {
  return SANDBOXES.has(`${component}/${id}`);
}

export interface PreparedSandbox {
  project: SandboxProject;
  openFile: string;
}

async function fetchJson<T>(url: string): Promise<T> {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`${url} answered ${response.status}`);
  return (await response.json()) as T;
}

/* Shared across cards: most examples on a page need the same registry items. */
const documents = new Map<string, Promise<RegistryDocument>>();
const prepared = new Map<string, Promise<PreparedSandbox>>();

function registryDocument(item: string): Promise<RegistryDocument> {
  let pending = documents.get(item);
  if (!pending) {
    pending = fetchJson<RegistryDocument>(registryUrl(item));
    // A failed fetch is not cached, so the next hover tries again.
    pending.catch(() => documents.delete(item));
    documents.set(item, pending);
  }
  return pending;
}

/** Fetches and assembles one example's project, once. */
export function prepareSandbox(component: string, id: string): Promise<PreparedSandbox> {
  const key = `${component}/${id}`;
  let pending = prepared.get(key);
  if (!pending) {
    pending = (async () => {
      const manifest = await fetchJson<SandboxManifest>(sandboxUrl(component, id));
      const items = await Promise.all(manifest.items.map(registryDocument));
      return { project: assembleProject(manifest, items), openFile: manifest.openFile };
    })();
    pending.catch(() => prepared.delete(key));
    prepared.set(key, pending);
  }
  return pending;
}

/** Opens a prepared project. Synchronous, so it can run inside the click. */
export function openSandbox({ project, openFile }: PreparedSandbox): void {
  sdk.openProject(project, { openFile, newWindow: true });
}

/* ------------------------------------------------------------------ */

export type DemoLinkStatus = "idle" | "loading" | "ready" | "error";

export interface DemoLink {
  id: string;
  label: string;
  /** Two-letter mark drawn in the button, as on the design. */
  mark: string;
  title: string;
  /** Opens the project when it is ready; otherwise starts preparing it. */
  open: () => void;
  /** Starts fetching the project, so the click that follows can open it. */
  prepare?: () => void;
  status?: DemoLinkStatus;
}
